/**
 * Test script for ko-debug.js
 */

const { createDebugHelper } = require('./ko-debug.js');

// Define a sample ViewModel with at least these properties:
// items, selectedItem, filterText, isLoading, totalCount
const sampleViewModel = {
  items: [],
  selectedItem: null,
  filterText: '',
  isLoading: false,
  totalCount: 0
};

// Create the debug helper
const helper = createDebugHelper(sampleViewModel);

// Test counter
let passed = 0;
let failed = 0;

/**
 * Helper to run a test
 * @param {string} testName - Description of the test
 * @param {Function} assertFn - Function that returns true if test passes
 */
function test(testName, assertFn) {
  const result = assertFn();
  if (result) {
    console.log(`PASS: ${testName}`);
    passed++;
  } else {
    console.log(`FAIL: ${testName}`);
    failed++;
  }
}

/**
 * Deep equality check for plain objects
 */
function deepEqual(a, b) {
  if (a === b) return true;
  if (a === null || b === null) return false;
  if (typeof a !== typeof b) return false;

  if (Array.isArray(a) && Array.isArray(b)) {
    if (a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) {
      if (!deepEqual(a[i], b[i])) return false;
    }
    return true;
  }

  if (typeof a === 'object') {
    const keysA = Object.keys(a).sort();
    const keysB = Object.keys(b).sort();
    if (keysA.length !== keysB.length) return false;
    for (let i = 0; i < keysA.length; i++) {
      if (keysA[i] !== keysB[i] || !deepEqual(a[keysA[i]], b[keysB[i]])) return false;
    }
    return true;
  }

  return false;
}

console.log('--- KnockoutJS Debug Helper Tests ---\n');

// Helper function to prepare assertions for the diagnosis result
function assertDiagnosis(missingProperty, expectedError, expectedSuggestion) {
  return function() {
    const result = helper.diagnoseMissingProperty(missingProperty);

    // Check structure
    if (typeof result.error !== 'boolean' ||
        typeof result.missingProperty !== 'string' ||
        !Array.isArray(result.availableProperties) ||
        (result.suggestion !== null && typeof result.suggestion !== 'string')) {
      console.log('  |-> ERROR: Invalid result structure');
      return false;
    }

    // Check error flag
    if (result.error !== expectedError) {
      return false;
    }

    // Check suggestion
    if (result.suggestion !== expectedSuggestion) {
      console.log('  |-> ERROR: Expected suggestion "' + expectedSuggestion + '", got "' + result.suggestion + '"');
      return false;
    }

    // Check available properties are sorted
    const sorted = [...result.availableProperties].sort();
    if (!deepEqual(result.availableProperties, sorted)) {
      console.log('  |-> ERROR: availableProperties is not sorted');
      return false;
    }

    return true;
  };
}

// Test 1: Diagnose missing property "item" (should suggest "items")
test(
  'Diagnose missing property "item" (should suggest "items")',
  assertDiagnosis('item', true, 'items')
);

// Test 2: Diagnose missing property "selctedItem" (should suggest "selectedItem")
test(
  'Diagnose missing property "selctedItem" (should suggest "selectedItem")',
  assertDiagnosis('selctedItem', true, 'selectedItem')
);

// Test 3: Diagnose missing property "completelyWrong" (should have null suggestion)
test(
  'Diagnose missing property "completelyWrong" (should have null suggestion)',
  assertDiagnosis('completelyWrong', true, null)
);

// Test 4: Diagnose missing property "isLoad" (should suggest "isLoading")
test(
  'Diagnose missing property "isLoad" (should suggest "isLoading")',
  assertDiagnosis('isLoad', true, 'isLoading')
);

// Additional validation tests
console.log('\n--- Additional Validation Tests ---\n');

// Verify available properties in result
test(
  'Available properties should include all viewModel properties',
  function() {
    const result = helper.diagnoseMissingProperty('nonexistent');
    const expectedProps = ['items', 'selectedItem', 'filterText', 'isLoading', 'totalCount'].sort();
    return deepEqual(result.availableProperties, expectedProps);
  }
);

// Verify distance <= 3 threshold
test(
  'Distance threshold: "totalllyWrong" (dist > 3) should have null suggestion',
  assertDiagnosis('totalllyWrong', true, null)
);

// Verify existing property returns error: false
test(
  'Existing property "items" should return error: false',
  function() {
    const result = helper.diagnoseMissingProperty('items');
    return result.error === false && result.suggestion === null;
  }
);

// Verify missingProperty field
test(
  'Missing property field should match input',
  function() {
    const result = helper.diagnoseMissingProperty('item');
    return result.missingProperty === 'item';
  }
);

// Print summary
console.log('\n--- Summary ---');
console.log(`Passed: ${passed}`);
console.log(`Failed: ${failed}`);
console.log(`Total: ${passed + failed}`);

// Exit with appropriate code
if (failed > 0) {
  process.exit(1);
}
process.exit(0);
EOF"}
